import { hasRoleAtLeast, type Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Whether `actor` may see `project`.
 *
 * `org` and `public` projects are visible to the whole tenant. A `private`
 * project is visible only to platform staff, an admin or owner, the project's
 * lead, or an explicit project member. Everyone else must be treated as if
 * the project did not exist.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (restrictedViewerId(actor) === undefined) return true;
  if (project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * User id a listing must apply the private-project filter for.
 * `undefined` means the actor sees every project in the org.
 */
export function restrictedViewerId(actor: Actor): UserId | undefined {
  if (actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin")) {
    return undefined;
  }
  return actor.userId;
}

async function assertProjectVisible(
  actor: Actor,
  project: Project,
  entity: string,
  id: string,
): Promise<void> {
  if (await canViewProject(actor, project)) return;
  throw new NotFoundError(entity, id);
}

