/**
 * Private projects are invisible to anyone who is not staff, an admin or
 * owner, the lead, or an explicit project member.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privatevis", "growth");
});

afterAll(() => {
  cleanup();
});

async function insertProject(
  name: string,
  visibility: Project["visibility"],
  leadId: Project["leadId"] = null,
): Promise<Project> {
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  return projectRepo.insertProject({
    orgId: tenant.org.id,
    name,
    slug,
    key: slug.slice(0, 4).toUpperCase() || "PRJ",
    description: null,
    visibility,
    leadId,
    color: "#6366f1",
    targetDate: null,
  });
}

function listInput(limit = 25, cursor: string | null = null) {
  return { orgId: tenant.org.id, limit, cursor };
}

async function collectProjects(actor: Actor): Promise<Project[]> {
  const found: Project[] = [];
  let cursor: string | null = null;
  let guard = 0;
  do {
    const page = await projectService.listProjects(actor, listInput(1, cursor));
    expect(page.total).toBeGreaterThanOrEqual(page.items.length);
    found.push(...page.items.map((item) => item.project));
    cursor = page.nextCursor;
    guard += 1;
  } while (cursor !== null && guard < 20);
  return found;
}

describe("private project visibility", () => {
  it("shows a private project only to staff, admins, the lead, and members", async () => {
    const secret = await insertProject("Secret One", "private");
    const open = await insertProject("Open One", "public");

    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.admin, secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, secret)).toBe(true);
    expect(
      await projectService.canViewProject(
        { ...tenant.actors.viewer, isPlatformStaff: true },
        secret,
      ),
    ).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, open)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.viewer, tenant.project)).toBe(
      true,
    );

    await expect(
      projectService.getProject(tenant.actors.member, tenant.org.id, secret.slug),
    ).rejects.toMatchObject({ name: "NotFoundError", entity: "Project", id: secret.slug });

    await expect(
      projectService.getProject(tenant.actors.admin, tenant.org.id, secret.slug),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    const memberIds = (await collectProjects(tenant.actors.member)).map((project) => project.id);
    expect(memberIds).not.toContain(secret.id);
    expect(memberIds).toContain(open.id);
    expect(memberIds).toContain(tenant.project.id);

    const memberPage = await projectService.listProjects(tenant.actors.member, listInput());
    const adminPage = await projectService.listProjects(tenant.actors.admin, listInput());
    expect(memberPage.total).toBe(memberIds.length);
    expect(adminPage.total).toBe(memberPage.total + 1);
    expect(adminPage.items.map((item) => item.project.id)).toContain(secret.id);

    const staffPage = await projectService.listProjects(
      { ...tenant.actors.viewer, isPlatformStaff: true },
      listInput(),
    );
    expect(staffPage.items.map((item) => item.project.id)).toContain(secret.id);
  });

  it("applies lead and membership changes on the next read", async () => {
    const secret = await insertProject("Secret Two", "private");
    const member = tenant.actors.member;
    const viewer = tenant.actors.viewer;

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: member.userId,
    });
    const led = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(await projectService.canViewProject(member, led!)).toBe(true);
    await expect(
      projectService.getProject(member, tenant.org.id, secret.slug),
    ).resolves.toMatchObject({ project: { id: secret.id } });

    await projectRepo.updateProject({
      orgId: tenant.org.id,
      projectId: secret.id,
      leadId: null,
    });
    const unled = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(await projectService.canViewProject(member, unled!)).toBe(false);

    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, viewer.userId);
    expect(await projectService.canViewProject(viewer, unled!)).toBe(true);
    const withMember = (await collectProjects(viewer)).map((project) => project.id);
    expect(withMember).toContain(secret.id);

    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, viewer.userId);
    expect(await projectService.canViewProject(viewer, unled!)).toBe(false);
    const withoutMember = (await collectProjects(viewer)).map((project) => project.id);
    expect(withoutMember).not.toContain(secret.id);
  });

  it("refuses project writes without changing the row", async () => {
    const secret = await insertProject("Secret Three", "private");
    const member = tenant.actors.member;

    await expect(
      projectService.updateProject(member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Hacked",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      projectService.archiveProject(member, {
        orgId: tenant.org.id,
        projectId: secret.id,
        archiveIssues: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const after = await projectRepo.findProjectById(tenant.org.id, secret.id);
    expect(after?.name).toBe("Secret Three");
    expect(after?.archivedAt).toBeNull();

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: secret.id,
      archiveIssues: false,
    });
    await expect(
      projectService.restoreProject(member, tenant.org.id, secret.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(
      (await projectRepo.findProjectById(tenant.org.id, secret.id))?.archivedAt,
    ).not.toBeNull();
  });

  it("hides a private project's issues, board, and comments", async () => {
    const secret = await insertProject("Secret Four", "private", tenant.userIds.admin);
    const member = tenant.actors.member;
    const admin = tenant.actors.admin;

    const issue = await issueService.createIssue(
      admin,
      issueInput(tenant.org.id, secret.id, { title: "Hidden work" }),
    );
    const visible = await issueService.createIssue(
      member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Visible work" }),
    );

    const memberIssues = await issueService.listIssues(member, listInput());
    expect(memberIssues.items.map((row) => row.id)).not.toContain(issue.id);
    expect(memberIssues.items.map((row) => row.id)).toContain(visible.id);
    expect(memberIssues.total).toBe(
      memberIssues.items.filter((row) => row.projectId !== secret.id).length,
    );

    const adminIssues = await issueService.listIssues(admin, listInput(100));
    expect(adminIssues.items.map((row) => row.id)).toContain(issue.id);
    expect(adminIssues.total).toBeGreaterThan(memberIssues.total);

    const scoped = await issueService.listIssues(member, {
      ...listInput(),
      projectId: secret.id,
    });
    expect(scoped.items).toEqual([]);
    expect(scoped.total).toBe(0);

    await expect(issueService.getIssue(member, tenant.org.id, issue.id)).rejects.toMatchObject({
      name: "NotFoundError",
      entity: "Issue",
      id: issue.id,
    });
    await expect(issueService.getBoard(member, tenant.org.id, secret.id)).rejects.toMatchObject({
      name: "NotFoundError",
      entity: "Project",
      id: secret.id,
    });
    await expect(
      issueService.getBoard(admin, tenant.org.id, secret.id),
    ).resolves.toEqual(expect.any(Array));

    const beforeCount = await issueRepo.countIssues(tenant.org.id, secret.id);
    await expect(
      issueService.createIssue(
        member,
        issueInput(tenant.org.id, secret.id, { title: "Should not land" }),
      ),
    ).rejects.toMatchObject({ entity: "Project", id: secret.id });
    expect(await issueRepo.countIssues(tenant.org.id, secret.id)).toBe(beforeCount);

    await expect(
      issueService.updateIssue(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Rewritten",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.title).toBe("Hidden work");

    await expect(
      issueService.changeIssueStatus(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "todo",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.assignIssue(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: member.userId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.moveIssue(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toStatus: "in_progress",
        toIndex: 0,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.archiveIssue(member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const untouched = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(untouched?.status).toBe("backlog");
    expect(untouched?.assigneeId).toBeNull();
    expect(untouched?.archivedAt).toBeNull();

    const comment = await commentService.createComment(admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "staff note",
      parentId: null,
      mentionedUserIds: [],
    });

    await expect(
      commentService.getThread(member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ entity: "Issue", id: issue.id });
    await expect(
      commentService.createComment(member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await commentRepo.countComments(tenant.org.id, issue.id)).toBe(1);

    await expect(
      commentService.updateComment(member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited",
      }),
    ).rejects.toMatchObject({ entity: "Comment", id: comment.id });
    await expect(
      commentService.deleteComment(member, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    const still = await commentRepo.findCommentById(tenant.org.id, comment.id);
    expect(still?.body).toBe("staff note");
    expect(still?.archivedAt).toBeNull();

    await projectMemberRepo.addProjectMember(tenant.org.id, secret.id, member.userId);
    await expect(issueService.getIssue(member, tenant.org.id, issue.id)).resolves.toMatchObject({
      issue: { id: issue.id },
    });
    const seen = await issueService.listIssues(member, listInput(100));
    expect(seen.items.map((row) => row.id)).toContain(issue.id);
    expect(seen.total).toBeGreaterThan(memberIssues.total);

    await projectMemberRepo.removeProjectMember(tenant.org.id, secret.id, member.userId);
    await expect(issueService.getIssue(member, tenant.org.id, issue.id)).rejects.toBeInstanceOf(
      NotFoundError,
    );
  });

  it("still permission-checks actors who are allowed to see the project", async () => {
    const secret = await insertProject("Secret Five", "private", tenant.userIds.viewer);
    await expect(
      projectService.getProject(tenant.actors.viewer, tenant.org.id, secret.slug),
    ).resolves.toMatchObject({ project: { id: secret.id } });
    await expect(
      projectService.updateProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId: secret.id,
        name: "Viewer edit",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    expect((await projectRepo.findProjectById(tenant.org.id, secret.id))?.name).toBe(
      "Secret Five",
    );
  });

  it("keeps cross-tenant reads on the tenant-scope error", async () => {
    const other = await createTenant("privatevisother", "growth");
    const secret = await insertProject("Secret Six", "private", tenant.userIds.owner);
    const { TenantScopeError } = await import("@/lib/tenant");
    await expect(
      projectService.getProject(other.actors.admin, tenant.org.id, secret.slug),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

