expect(await projectService.canViewProject(member, led!)).toBe(true);
await expect(
  projectService.getProject(member, tenant.org.id, secret.slug),
).resolves.toMatchObject({ project: { id: secret.id } });
const ledIds = (await collectProjects(member)).map((project) => project.id);
expect(ledIds).toContain(secret.id);

const ledIssues = await issueService.createIssue(
  member,
  issueInput(tenant.org.id, secret.id, { title: "Lead can file" }),
);
const issuePage = await issueService.listIssues(member, listInput(100));
expect(issuePage.items.map((row) => row.id)).toContain(ledIssues.id);

const unled = await projectRepo.findProjectById(tenant.org.id, secret.id);
expect(await projectService.canViewProject(member, unled!)).toBe(false);
const unledIds = (await collectProjects(member)).map((project) => project.id);
expect(unledIds).not.toContain(secret.id);
const hiddenIssues = await issueService.listIssues(member, listInput(100));
expect(hiddenIssues.items.map((row) => row.id)).not.toContain(ledIssues.id);

